package com.catalogix.search.config;
import org.springframework.amqp.core.*; import org.springframework.amqp.support.converter.JacksonJsonMessageConverter; import org.springframework.amqp.support.converter.MessageConverter; import org.springframework.context.annotation.*;
@Configuration public class RabbitMQConfig { @Bean TopicExchange eventsExchange(){return new TopicExchange("catalogix.events",true,false);} @Bean MessageConverter json(){return new JacksonJsonMessageConverter();} @Bean Queue productQueue(){return QueueBuilder.durable("search.product-events").quorum().build();} @Bean Binding binding(){return BindingBuilder.bind(productQueue()).to(eventsExchange()).with("product.#");} }
